-- Synthetic legacy database: the "up" statements of the five Doctrine
-- migrations of master:src/Migrations, verbatim and in order (Version20180626223216,
-- Version20200118004840, Version20250701154230, Version20250701155112,
-- Version20250701161732), plus the Doctrine version table. No data.

CREATE TABLE migration_versions (version VARCHAR(191) NOT NULL, executed_at TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, execution_time INT DEFAULT NULL, PRIMARY KEY(version));

-- Version20180626223216
CREATE SCHEMA users;
CREATE SEQUENCE users.users_id_seq INCREMENT BY 1 MINVALUE 1 START 1;
CREATE SEQUENCE users.invites_id_seq INCREMENT BY 1 MINVALUE 1 START 1;
CREATE TABLE users.users (id INT NOT NULL, username VARCHAR(25) NOT NULL, password TEXT NOT NULL, email VARCHAR(254) NOT NULL, roles JSON NOT NULL, created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, PRIMARY KEY(id));
CREATE UNIQUE INDEX UNIQ_338ADFC4F85E0677 ON users.users (username);
CREATE UNIQUE INDEX UNIQ_338ADFC4E7927C74 ON users.users (email);
CREATE TABLE users.invites (id INT NOT NULL, user_id INT NOT NULL, used_by_id INT DEFAULT NULL, code VARCHAR(32) NOT NULL, PRIMARY KEY(id));
CREATE UNIQUE INDEX UNIQ_93848FA877153098 ON users.invites (code);
CREATE INDEX IDX_93848FA8A76ED395 ON users.invites (user_id);
CREATE INDEX IDX_93848FA84C2B72A8 ON users.invites (used_by_id);
CREATE TABLE users.api_tokens (key VARCHAR(32) NOT NULL, user_id INT NOT NULL, created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, PRIMARY KEY(key));
CREATE INDEX IDX_C46A74A9A76ED395 ON users.api_tokens (user_id);
ALTER TABLE users.invites ADD CONSTRAINT FK_93848FA8A76ED395 FOREIGN KEY (user_id) REFERENCES users.users (id) NOT DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE users.invites ADD CONSTRAINT FK_93848FA84C2B72A8 FOREIGN KEY (used_by_id) REFERENCES users.users (id) NOT DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE users.api_tokens ADD CONSTRAINT FK_C46A74A9A76ED395 FOREIGN KEY (user_id) REFERENCES users.users (id) NOT DEFERRABLE INITIALLY IMMEDIATE;

-- Version20200118004840
CREATE TABLE users.password_reset_tokens (code TEXT NOT NULL, user_id INT NOT NULL, valid_until TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, PRIMARY KEY(code));
CREATE INDEX IDX_261A8E65A76ED395 ON users.password_reset_tokens (user_id);
ALTER TABLE users.password_reset_tokens ADD CONSTRAINT FK_CCD4B965A76ED395 FOREIGN KEY (user_id) REFERENCES users.users (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE;

-- Version20250701154230
ALTER TABLE users.users ALTER COLUMN id SET DEFAULT nextval('users.users_id_seq');
ALTER SEQUENCE users.users_id_seq OWNED BY users.users.id;
SELECT setval('users.users_id_seq', COALESCE((SELECT MAX(id) FROM users.users), 1), false);
ALTER TABLE users.invites ALTER COLUMN id SET DEFAULT nextval('users.invites_id_seq');
ALTER SEQUENCE users.invites_id_seq OWNED BY users.invites.id;
SELECT setval('users.invites_id_seq', COALESCE((SELECT MAX(id) FROM users.invites), 1), false);

-- Version20250701155112
ALTER TABLE users.users ALTER COLUMN id DROP DEFAULT;
ALTER TABLE users.users ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
DROP SEQUENCE IF EXISTS users.users_id_seq;
ALTER TABLE users.invites ALTER COLUMN id DROP DEFAULT;
ALTER TABLE users.invites ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
DROP SEQUENCE IF EXISTS users.invites_id_seq;

-- Version20250701161732
DO $do$ DECLARE max_id integer; BEGIN SELECT COALESCE(MAX(id), 0) + 1 INTO max_id FROM users.users; EXECUTE format('ALTER TABLE users.users ALTER COLUMN id RESTART WITH %s', max_id); END $do$;
DO $do$ DECLARE max_id integer; BEGIN SELECT COALESCE(MAX(id), 0) + 1 INTO max_id FROM users.invites; EXECUTE format('ALTER TABLE users.invites ALTER COLUMN id RESTART WITH %s', max_id); END $do$;

